from __future__ import annotations
from itertools import product


def escape_capacity(targets: list[int]) -> int:
    return sum(s - 1 for s in targets)


def vertex_ramsey_number(targets: list[int]) -> int:
    return 1 + escape_capacity(targets)


def arrows(n: int, targets: list[int]) -> bool:
    return escape_capacity(targets) < n


def has_monochromatic_clique(coloring: tuple[int, ...], targets: list[int]) -> bool:
    n = len(coloring)
    for color, s in enumerate(targets):
        if sum(1 for v in range(n) if coloring[v] == color) >= s:
            return True
    return False


def arrows_bruteforce(n: int, targets: list[int]) -> bool:
    r = len(targets)
    for coloring in product(range(r), repeat=n):
        if not has_monochromatic_clique(coloring, targets):
            return False
    return True


if __name__ == "__main__":
    for targets in [[2, 2], [2, 2, 2], [3, 2], [3, 3]]:
        print(f"targets={targets}, threshold n_c={vertex_ramsey_number(targets)}")
        for n in range(1, vertex_ramsey_number(targets) + 2):
            f, b = arrows(n, targets), arrows_bruteforce(n, targets)
            assert f == b, "theorem contradicted!"
            print(f"  n={n}: formula={f} brute={b}")

from __future__ import annotations
from typing import Optional


def escape_capacity(targets: list[int]) -> int:
    return sum(s - 1 for s in targets)


def extremal_coloring(n: int, targets: list[int]) -> Optional[tuple[int, ...]]:
    if n > escape_capacity(targets):
        return None
    coloring: list[int] = []
    for color, s in enumerate(targets):
        coloring.extend([color] * (s - 1))
        if len(coloring) >= n:
            break
    return tuple(coloring[:n])


def escapes(coloring: tuple[int, ...], targets: list[int]) -> bool:
    n = len(coloring)
    return all(sum(1 for v in range(n) if coloring[v] == c) < s
               for c, s in enumerate(targets))


if __name__ == "__main__":
    for targets, n in [([3, 3], 4), ([2, 2, 2], 3), ([4, 2], 4)]:
        c = extremal_coloring(n, targets)
        assert c is not None and escapes(c, targets)
        sizes = [c.count(i) for i in range(len(targets))]
        print(f"targets={targets}, n={n}: coloring={c}, class sizes={sizes}, "
              f"caps={[s - 1 for s in targets]} -> escapes")

from __future__ import annotations
from math import prod


def vertex_ramsey_number_from_omegas(omegas: list[int]) -> int:
    return 1 + sum(w - 1 for w in omegas)


def turan_density_from_omegas(omegas: list[int]) -> float:
    psi = prod(w - 1 for w in omegas)
    return 1 - 1 / psi


if __name__ == "__main__":
    for omegas in [[3, 3], [3, 4, 3], [4, 4]]:
        atoms = [w - 1 for w in omegas]
        print(f"omega={omegas}, atoms(omega-1)={atoms}")
        print(f"  VERTEX  sum(omega-1)={sum(atoms)}  "
              f"vertex-Ramsey number={vertex_ramsey_number_from_omegas(omegas)}")
        print(f"  EDGE    psi=prod(omega-1)={prod(atoms)}  "
              f"pi_c=1-1/psi={turan_density_from_omegas(omegas):.4f}")

